customCSS:
/* Center the whole form and boxes to the center of the page */
.np-form {
    font-family: Arial, sans-serif;
    font-weight: bold;
    border-radius: 5px;
    background-color: rgb(156, 215, 229); /* Background color */
    padding: 24px;
    width: 95%; /* Adjust width as needed to fit the section better */
    max-width: 800px; /* Maximum width to prevent it from becoming too wide */
    margin: auto; /* Center the form horizontally */
    font-size: 14px; /* Increase font size */
    border: 1px solid black; /* Black border */
    box-shadow: 0 2px 5px rgba(0,0,0,0.1); /* Optional: adds a shadow for better visibility */
}

.slds-tabs_default, .slds-tabset__content {
    background-color: rgb(233, 237, 238) !important;
    font-size: 15px !important;
}

.slds-truncate {
    font-size: 15px !important; /* Adjust the font size as needed */
    white-space: normal; /* Allow text to wrap if space is available */
}

.np-form::after {
    content: "";
    display: table;
    clear: both;
}

.np-form .col-25,
.np-form .col-75 {
    float: left;
    width: 50%;
    margin-top: 10px;
}

/* Responsive layout - when the screen is less than 1062px wide, make the two columns stack on top of each other instead of next to each other */
@media screen and (max-width: 1062px) {
    .np-form .col-25,
    .np-form .col-75,
    .np-form input[type=submit] {
        width: 100%;
        margin-top: 0;
    }

    .np-form button[type="submit"] {
    background-color: #4CAF50; /* Green background color */
    color: white; /* White text color */
    padding: 12px 20px; /* Padding for the button */
    border: none; /* Remove default border */
    border-radius: 5px; /* Rounded corners */
    cursor: pointer; /* Pointer cursor on hover */
    font-size: 16px; /* Font size */
    text-align: center; /* Center text */
    display: block; /* Block display */
    margin: 20px auto; /* Center button horizontally with margin */
    transition: background-color 0.3s ease; /* Smooth transition for background color */
}

    .np-form select {
        width: 100%; 
    }
}
